-- ============================================================================
--  Moziki · initial schema
--  Community cooperative finance for the DRC (CDF), double-entry enforced
--  in PostgreSQL (constraint trigger), immutable ledger, USSD-ready sessions.
-- ============================================================================

-- Human-readable, gap-tolerant identifiers generated by the database.
CREATE SEQUENCE transaction_reference_seq START WITH 1;
CREATE SEQUENCE member_number_seq START WITH 1;

CREATE TABLE cooperatives (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code            VARCHAR(16)  NOT NULL UNIQUE,
    name            VARCHAR(160) NOT NULL,
    country         VARCHAR(2)   NOT NULL DEFAULT 'CD',
    currency        VARCHAR(3)   NOT NULL DEFAULT 'CDF',
    default_locale  VARCHAR(2)   NOT NULL DEFAULT 'fr'
                    CHECK (default_locale IN ('en', 'fr', 'sw')),
    timezone        VARCHAR(64)  NOT NULL DEFAULT 'Africa/Kinshasa',
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- ----------------------------------------------------------------------------
--  People. A user belongs to one cooperative in phase 1; the USSD channel
--  identifies the caller by phone, hence the global uniqueness.
-- ----------------------------------------------------------------------------
CREATE TABLE users (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    cooperative_id  UUID         NOT NULL REFERENCES cooperatives (id) ON DELETE RESTRICT,
    member_number   VARCHAR(24)  NOT NULL,
    full_name       VARCHAR(160) NOT NULL,
    phone           VARCHAR(16)  NOT NULL UNIQUE
                    CHECK (phone ~ '^\+[1-9][0-9]{7,14}$'),
    email           VARCHAR(190) UNIQUE,
    password_hash   VARCHAR(100) NOT NULL,
    role            VARCHAR(16)  NOT NULL
                    CHECK (role IN ('MEMBER', 'LEADER', 'AUDITOR')),
    status          VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE'
                    CHECK (status IN ('ACTIVE', 'SUSPENDED')),
    locale          VARCHAR(2)   NOT NULL DEFAULT 'fr'
                    CHECK (locale IN ('en', 'fr', 'sw')),
    last_login_at   TIMESTAMPTZ,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_users_member_number_per_coop UNIQUE (cooperative_id, member_number)
);

CREATE INDEX idx_users_cooperative_role ON users (cooperative_id, role);

-- ----------------------------------------------------------------------------
--  Chart of accounts, one set per cooperative plus one sub-ledger account per
--  member for savings and shares.
--  balance_minor is a cached, signed running balance (debit positive) updated
--  in the same database transaction as the ledger lines; it can always be
--  re-derived from ledger_entries and the auditor endpoint verifies it.
-- ----------------------------------------------------------------------------
CREATE TABLE accounts (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    cooperative_id  UUID         NOT NULL REFERENCES cooperatives (id) ON DELETE RESTRICT,
    member_id       UUID         REFERENCES users (id) ON DELETE RESTRICT,
    code            VARCHAR(32)  NOT NULL,
    name            VARCHAR(120) NOT NULL,
    type            VARCHAR(16)  NOT NULL
                    CHECK (type IN ('ASSET', 'LIABILITY', 'EQUITY', 'INCOME', 'EXPENSE')),
    category        VARCHAR(24)  NOT NULL
                    CHECK (category IN ('CASH', 'MOBILE_MONEY', 'SAVINGS', 'SHARES',
                                        'LOANS', 'FEES', 'INTEREST', 'OTHER')),
    wallet_provider VARCHAR(16)
                    CHECK (wallet_provider IS NULL OR wallet_provider IN ('AIRTEL', 'ORANGE', 'MPESA')),
    currency        VARCHAR(3)   NOT NULL DEFAULT 'CDF',
    balance_minor   BIGINT       NOT NULL DEFAULT 0,
    is_system       BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_accounts_code_per_coop UNIQUE (cooperative_id, code),
    CONSTRAINT chk_accounts_member_target CHECK (
        (member_id IS NULL) OR (category IN ('SAVINGS', 'SHARES', 'LOANS'))
    )
);

CREATE UNIQUE INDEX uq_accounts_member_category
    ON accounts (cooperative_id, member_id, category)
    WHERE member_id IS NOT NULL;

CREATE INDEX idx_accounts_cooperative ON accounts (cooperative_id);
CREATE INDEX idx_accounts_member ON accounts (member_id) WHERE member_id IS NOT NULL;

-- ----------------------------------------------------------------------------
--  Transactions (journal headers). A transaction is immutable once posted:
--  corrections happen through a linked reversal. `source` is prepared for the
--  future USSD channel without schema changes.
-- ----------------------------------------------------------------------------
CREATE TABLE transactions (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    cooperative_id          UUID        NOT NULL REFERENCES cooperatives (id) ON DELETE RESTRICT,
    reference               VARCHAR(32) NOT NULL UNIQUE,
    kind                    VARCHAR(24) NOT NULL
                            CHECK (kind IN ('DEPOSIT', 'WITHDRAWAL', 'SHARE_PURCHASE',
                                            'LOAN_DISBURSEMENT', 'LOAN_REPAYMENT', 'FEE',
                                            'REVERSAL', 'ADJUSTMENT')),
    channel                 VARCHAR(20) NOT NULL
                            CHECK (channel IN ('CASH', 'AIRTEL_MONEY', 'ORANGE_MONEY',
                                               'MPESA', 'BANK', 'INTERNAL')),
    source                  VARCHAR(12) NOT NULL DEFAULT 'WEB'
                            CHECK (source IN ('WEB', 'USSD', 'SYSTEM')),
    status                  VARCHAR(16) NOT NULL DEFAULT 'POSTED'
                            CHECK (status IN ('POSTED', 'REVERSED')),
    amount_minor            BIGINT      NOT NULL CHECK (amount_minor > 0),
    currency                VARCHAR(3)  NOT NULL DEFAULT 'CDF',
    description             VARCHAR(500) NOT NULL,
    external_ref            VARCHAR(80),
    idempotency_key         VARCHAR(80),
    member_id               UUID        REFERENCES users (id) ON DELETE RESTRICT,
    created_by              UUID        REFERENCES users (id) ON DELETE RESTRICT,
    reverses_transaction_id UUID UNIQUE REFERENCES transactions (id) ON DELETE RESTRICT,
    reversal_reason         VARCHAR(300),
    reversed_at             TIMESTAMPTZ,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    posted_at               TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_transactions_reversal CHECK (
        (kind = 'REVERSAL') = (reverses_transaction_id IS NOT NULL)
    ),
    CONSTRAINT uq_transactions_idempotency UNIQUE (cooperative_id, idempotency_key)
);

CREATE UNIQUE INDEX uq_transactions_external_ref
    ON transactions (cooperative_id, channel, external_ref)
    WHERE external_ref IS NOT NULL;

CREATE INDEX idx_transactions_cooperative_created
    ON transactions (cooperative_id, created_at DESC);
CREATE INDEX idx_transactions_member ON transactions (member_id, created_at DESC)
    WHERE member_id IS NOT NULL;

-- ----------------------------------------------------------------------------
--  Journal lines. Exactly one line per account per transaction, positive
--  amounts, explicit side. Append-only at the database level.
-- ----------------------------------------------------------------------------
CREATE TABLE ledger_entries (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    transaction_id UUID   NOT NULL REFERENCES transactions (id) ON DELETE RESTRICT,
    account_id    UUID    NOT NULL REFERENCES accounts (id) ON DELETE RESTRICT,
    direction     VARCHAR(6) NOT NULL CHECK (direction IN ('DEBIT', 'CREDIT')),
    amount_minor  BIGINT  NOT NULL CHECK (amount_minor > 0),
    line_no       SMALLINT NOT NULL CHECK (line_no > 0),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_ledger_entries_line UNIQUE (transaction_id, line_no),
    CONSTRAINT uq_ledger_entries_account UNIQUE (transaction_id, account_id)
);

CREATE INDEX idx_ledger_entries_account ON ledger_entries (account_id);
CREATE INDEX idx_ledger_entries_transaction ON ledger_entries (transaction_id);

-- ----------------------------------------------------------------------------
--  Append-only audit trail for leader accountability.
-- ----------------------------------------------------------------------------
CREATE TABLE audit_logs (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    cooperative_id  UUID        NOT NULL REFERENCES cooperatives (id) ON DELETE RESTRICT,
    actor_id        UUID        REFERENCES users (id) ON DELETE RESTRICT,
    action          VARCHAR(48) NOT NULL,
    entity_type     VARCHAR(40) NOT NULL,
    entity_id       UUID,
    summary         VARCHAR(500) NOT NULL,
    metadata        JSONB       NOT NULL DEFAULT '{}'::JSONB,
    ip_address      VARCHAR(64),
    user_agent      VARCHAR(400),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_audit_logs_cooperative_created
    ON audit_logs (cooperative_id, created_at DESC);

-- ----------------------------------------------------------------------------
--  USSD groundwork: sessions for basic feature phones. The web PWA does not
--  use these yet; the ledger/tables are ready for the USSD gateway phase.
-- ----------------------------------------------------------------------------
CREATE TABLE ussd_sessions (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    phone           VARCHAR(16) NOT NULL CHECK (phone ~ '^\+[1-9][0-9]{7,14}$'),
    cooperative_id  UUID REFERENCES cooperatives (id) ON DELETE RESTRICT,
    user_id         UUID REFERENCES users (id) ON DELETE RESTRICT,
    locale          VARCHAR(2) NOT NULL DEFAULT 'fr'
                    CHECK (locale IN ('en', 'fr', 'sw')),
    state           VARCHAR(24) NOT NULL DEFAULT 'IDLE'
                    CHECK (state IN ('IDLE', 'AUTHENTICATING', 'MENU',
                                     'CONFIRMING', 'COMPLETED', 'EXPIRED')),
    context         JSONB NOT NULL DEFAULT '{}'::JSONB,
    last_activity_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at      TIMESTAMPTZ NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_ussd_sessions_phone ON ussd_sessions (phone, last_activity_at DESC);
CREATE INDEX idx_ussd_sessions_expiry ON ussd_sessions (expires_at);

-- ============================================================================
--  Integrity functions and triggers
-- ============================================================================

CREATE OR REPLACE FUNCTION moziki_touch_updated_at() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_cooperatives_touch
    BEFORE UPDATE ON cooperatives
    FOR EACH ROW EXECUTE FUNCTION moziki_touch_updated_at();

CREATE TRIGGER trg_users_touch
    BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION moziki_touch_updated_at();

CREATE TRIGGER trg_accounts_touch
    BEFORE UPDATE ON accounts
    FOR EACH ROW EXECUTE FUNCTION moziki_touch_updated_at();

-- Defers to commit time so the complete set of lines of a transaction is known.
CREATE OR REPLACE FUNCTION moziki_assert_transaction_balanced() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
DECLARE
    v_status        VARCHAR(16);
    v_coop          UUID;
    v_currency      VARCHAR(3);
    v_total_debits  BIGINT;
    v_total_credits BIGINT;
    v_line_count    INTEGER;
BEGIN
    SELECT status, cooperative_id, currency, amount_minor
      INTO v_status, v_coop, v_currency, v_total_debits
      FROM transactions
     WHERE id = NEW.transaction_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'ledger entry references unknown transaction %', NEW.transaction_id
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    IF v_status <> 'POSTED' THEN
        RAISE EXCEPTION 'ledger entries may only belong to a POSTED transaction (transaction % is %)',
            NEW.transaction_id, v_status USING ERRCODE = 'check_violation';
    END IF;

    IF NOT EXISTS (
        SELECT 1
          FROM accounts a
         WHERE a.id = NEW.account_id
           AND a.cooperative_id = v_coop
           AND a.currency = v_currency
    ) THEN
        RAISE EXCEPTION 'account % does not belong to cooperative % or has a different currency',
            NEW.account_id, v_coop USING ERRCODE = 'check_violation';
    END IF;

    SELECT COUNT(*),
           COALESCE(SUM(amount_minor) FILTER (WHERE direction = 'DEBIT'), 0),
           COALESCE(SUM(amount_minor) FILTER (WHERE direction = 'CREDIT'), 0)
      INTO v_line_count, v_total_debits, v_total_credits
      FROM ledger_entries
     WHERE transaction_id = NEW.transaction_id;

    IF v_line_count < 2 THEN
        RAISE EXCEPTION 'transaction % must have at least two ledger lines', NEW.transaction_id
            USING ERRCODE = 'check_violation';
    END IF;

    IF v_total_debits <> v_total_credits OR v_total_debits = 0 THEN
        RAISE EXCEPTION 'unbalanced transaction %: debits=% credits=% (double entry violation)',
            NEW.transaction_id, v_total_debits, v_total_credits
            USING ERRCODE = 'check_violation';
    END IF;

    IF v_total_debits <> (SELECT amount_minor FROM transactions WHERE id = NEW.transaction_id) THEN
        RAISE EXCEPTION 'transaction % header amount does not match its debit total',
            NEW.transaction_id USING ERRCODE = 'check_violation';
    END IF;

    RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER trg_ledger_entries_balanced
    AFTER INSERT ON ledger_entries
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION moziki_assert_transaction_balanced();

CREATE OR REPLACE FUNCTION moziki_block_ledger_mutation() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'ledger_entries is append-only; % is forbidden, post a reversal instead', TG_OP
        USING ERRCODE = 'integrity_constraint_violation';
END;
$$;

CREATE TRIGGER trg_ledger_entries_immutable
    BEFORE UPDATE OR DELETE ON ledger_entries
    FOR EACH ROW EXECUTE FUNCTION moziki_block_ledger_mutation();

CREATE OR REPLACE FUNCTION moziki_guard_transaction_mutation() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'transactions are append-only; post a reversal instead'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;

    IF NEW.cooperative_id <> OLD.cooperative_id
       OR NEW.reference <> OLD.reference
       OR NEW.kind <> OLD.kind
       OR NEW.channel <> OLD.channel
       OR NEW.source <> OLD.source
       OR NEW.amount_minor <> OLD.amount_minor
       OR NEW.currency <> OLD.currency
       OR NEW.description <> OLD.description
       OR NEW.created_at <> OLD.created_at
       OR NEW.member_id IS DISTINCT FROM OLD.member_id
       OR NEW.created_by IS DISTINCT FROM OLD.created_by
       OR NEW.reverses_transaction_id IS DISTINCT FROM OLD.reverses_transaction_id
    THEN
        RAISE EXCEPTION 'posted transaction % is immutable except for its reversal status', OLD.id
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;

    IF OLD.status = 'REVERSED' AND NEW.status <> 'REVERSED' THEN
        RAISE EXCEPTION 'a reversed transaction cannot return to POSTED'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;

    IF NEW.status = 'REVERSED' AND NEW.reversed_at IS NULL THEN
        RAISE EXCEPTION 'reversing a transaction requires reversed_at'
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_transactions_immutable
    BEFORE UPDATE OR DELETE ON transactions
    FOR EACH ROW EXECUTE FUNCTION moziki_guard_transaction_mutation();

CREATE OR REPLACE FUNCTION moziki_block_audit_mutation() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_logs is append-only; % is forbidden', TG_OP
        USING ERRCODE = 'integrity_constraint_violation';
END;
$$;

CREATE TRIGGER trg_audit_logs_immutable
    BEFORE UPDATE OR DELETE ON audit_logs
    FOR EACH ROW EXECUTE FUNCTION moziki_block_audit_mutation();

-- Reconciliation helper: the authoritative balance derived from the journal.
CREATE OR REPLACE VIEW v_account_ledger_balances AS
SELECT a.id AS account_id,
       a.cooperative_id,
       COALESCE(SUM(CASE WHEN e.direction = 'DEBIT' THEN e.amount_minor
                         WHEN e.direction = 'CREDIT' THEN -e.amount_minor
                         ELSE 0 END), 0) AS ledger_balance_minor
  FROM accounts a
  LEFT JOIN ledger_entries e ON e.account_id = a.id
 GROUP BY a.id, a.cooperative_id;
